package com.pabonaki.model; import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;@Document("users") public class User{@Id private String id;private String name;@Indexed(unique=true) private String email;private String passwordHash;private String role="CUSTOMER";private String firstName,lastName,phone,gender,dateOfBirth,profileImageUrl;private Instant createdAt=Instant.now();public String getId(){return id;}public void setId(String v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public Instant getCreatedAt(){return createdAt;}public String getFirstName(){return firstName;}public void setFirstName(String v){firstName=v;}public String getLastName(){return lastName;}public void setLastName(String v){lastName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getProfileImageUrl(){return profileImageUrl;}public void setProfileImageUrl(String v){profileImageUrl=v;}public String getGender(){return gender;}public void setGender(String v){gender=v;}public String getDateOfBirth(){return dateOfBirth;}public void setDateOfBirth(String v){dateOfBirth=v;}}
